INSERT INTO Lek (ID, Nazwa, KodEAN, CenaDetaliczna, DataWprowadzenia, ProducentID, OpisLeku) VALUES (638, 'Metamizole Kalceks, 500 mg/ml, 5 amp. 2 ml', '4750341001490', 9.69, DATE '2018-01-23', 32, 'Metamizole Kalceks (Metamizolum natricum monohydricum), 500 mg/ml, Roztwór do wstrzykiwań. Opakowanie: 5 amp. 2 ml. Lek przeciwbolowy i przeciwgoraczkowy (pirazolony, np. metamizol), stosowany przy silnym bolu, bolu glowy i goraczce (ATC N02BB02). Kategoria dostepnosci: Rp - lek wydawany na recepte. Substancja czynna: Metamizolum natricum monohydricum 500 mg/ml.');
